using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;
[InitializeOnLoad]public static class BusShelterFinish{static BusShelterFinish(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("BusShelterFinish.request"))return;File.Delete("BusShelterFinish.request");try{var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scenes/Oasis/3D/Prefeb/Bus stop.prefab");var mat=source.GetComponent<Renderer>().sharedMaterial;var original=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scenes/Oasis/BusShelterUpgrade/Bus Shelter Shared Near.asset");var b=original.bounds; // Retain original native center and ground from the before probe.
var bounds=new Bounds(new Vector3(-.1552065f,-.7563317f,1.659035f),new Vector3(4.339939f,1.8250166f,3.324406f));for(int l=0;l<2;l++){var target=AssetDatabase.LoadAssetAtPath<Mesh>("Assets/Scenes/Oasis/BusShelterUpgrade/Bus Shelter Shared "+(l==0?"Near":"Far")+".asset");var fresh=StackHouse3DSigns.BuildBusShelter(l==0,bounds,mat);target.Clear();target.indexFormat=fresh.indexFormat;target.vertices=fresh.vertices;for(int ch=0;ch<8;ch++){var uv=new List<Vector4>();fresh.GetUVs(ch,uv);if(uv.Count>0)target.SetUVs(ch,uv);}target.normals=fresh.normals;target.tangents=fresh.tangents;target.triangles=fresh.triangles;target.RecalculateBounds();EditorUtility.SetDirty(target);UnityEngine.Object.DestroyImmediate(fresh);}AssetDatabase.SaveAssets();File.WriteAllText("FinalEnvironmentRoadReview/BusShelterFinish.txt","SUCCESS side advert moved clear of support panels; rear metal and right-end concrete reuse original atlas islands; route text sampling refined; same shared mesh assets updated across all source prefab instances. Shader errors="+ShaderUtil.ShaderHasError(mat.shader));}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/BusShelterFinish.txt",e.ToString());}}}
